import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { TestTube2 } from "lucide-react";
import { useState } from "react";

// Card for each Health Package
interface HealthPackageCardProps {
  discount: string;
  title: string;
  testsCount: number;
  description: string;
  originalPrice: number;
  price: number;
  onAddToCart?: () => void;
}

export const HealthPackageCard = ({
  discount,
  title,
  testsCount,
  description,
  originalPrice,
  price,
  onAddToCart,
}: HealthPackageCardProps) => {
  return (
    <Card className="relative overflow-hidden bg-gradient-to-br from-white to-blue-50 border border-blue-100 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 rounded-2xl">
      <div className="p-6">
        <Badge className="absolute top-4 left-4 bg-yellow-300 text-yellow-900 font-semibold px-3 py-1 rounded-full">
          {discount}
        </Badge>
        <div className="flex items-start justify-between mb-4 mt-8">
          <div className="flex-1">
            <h3 className="text-xl font-bold text-blue-700 mb-2">{title}</h3>
            <p className="text-sm text-blue-600 font-medium mb-3">
              Includes {testsCount} Tests
            </p>
          </div>
          <div className="bg-blue-100 p-3 rounded-full">
            <TestTube2 className="w-6 h-6 text-blue-600" />
          </div>
        </div>
        <p className="text-sm text-blue-600 mb-6 line-clamp-2 min-h-[40px]">
          {description}
        </p>

        <div className="flex items-end justify-between mt-6 pt-4 border-t border-blue-100">
          <div>
            <p className="text-sm text-gray-400 line-through mb-1">
              Rs. {originalPrice.toLocaleString()}
            </p>
            <p className="text-2xl font-bold text-blue-900">
              Rs. {price.toLocaleString()}
            </p>
          </div>
          <Button 
            onClick={onAddToCart}
            className="bg-gradient-to-r from-blue-600 to-blue-500 hover:from-blue-700 hover:to-blue-600 text-white shadow-md font-semibold px-6 rounded-lg"
          >
            Add to Cart
          </Button>
        </div>
      </div>
    </Card>
  );
};

// Package carousel/section
const healthPackages = [
  {
    id: 1,
    discount: "66% off",
    title: "Energy Package",
    testsCount: 15,
    description: "Liver Function Test, 25 OH Cholecalciferol (D2+D3), Fasting Insulin & Glucose",
    originalPrice: 4360,
    price: 1500,
  },
  {
    id: 2,
    discount: "63% off",
    title: "Gym Package - TN",
    testsCount: 53,
    description: "Glyco Hemoglobin (HbA1c), Liver Function Test, TSH, Lipid Profile, Urea, Creatinine, Uric Acid, 25...",
    originalPrice: 7815,
    price: 2899,
  },
  {
    id: 3,
    discount: "67% off",
    title: "Her Advanced",
    testsCount: 93,
    description: "CBC, ESR, Glucose - Fasting, Glucose - Post Prandial, Glyco Hemoglobin (HbA1c), Liver Functi...",
    originalPrice: 12735,
    price: 4199,
  },
];

export const PopularHealthPackages = () => {
  const [activeSlide, setActiveSlide] = useState(0);

  return (
    <section
      className="py-16 px-4 bg-gradient-to-br from-[#B4E9FF] via-blue-50 to-[#e0f7fa]"
      style={{
        backgroundImage:
          "linear-gradient(120deg, #B4E9FF 0%, #e0f7fa 100%)",
      }}
    >
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col sm:flex-row items-center justify-between mb-12 gap-4">
          <h2 className="text-4xl font-bold text-blue-900">
            Popular Health Packages
          </h2>
          <Button 
            variant="outline"
            className="bg-gradient-to-r from-blue-700 to-blue-500 hover:from-blue-800 hover:to-blue-500 text-white border-0 shadow-lg font-semibold px-8 rounded-lg"
          >
            View All
          </Button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-7 mb-8">
          {healthPackages.map((pkg) => (
            <HealthPackageCard
              key={pkg.id}
              discount={pkg.discount}
              title={pkg.title}
              testsCount={pkg.testsCount}
              description={pkg.description}
              originalPrice={pkg.originalPrice}
              price={pkg.price}
              onAddToCart={() => console.log(`Added ${pkg.title} to cart`)}
            />
          ))}
        </div>
        {/* Slideshow "dots" */}
        <div className="flex justify-center gap-2">
          {[...Array(healthPackages.length)].map((_, index) => (
            <button
              key={index}
              onClick={() => setActiveSlide(index)}
              className={`w-3 h-3 rounded-full transition-all duration-300 ${
                index === activeSlide 
                  ? "bg-blue-600 w-8" 
                  : "bg-blue-300 hover:bg-blue-400"
              }`}
              aria-label={`Go to slide ${index + 1}`}
              style={{
                transition: "width 0.2s, background 0.2s"
              }}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

